.card__header { margin-bottom: 1.25rem; }

.card__header h1 {
  margin: 0 0 0.5rem;
  font-size: 1.625rem;
  letter-spacing: -0.01em;
}

.card__lede {
  margin: 0;
  color: var(--muted);
}

.required-legend {
  font-size: 0.875rem;
  color: var(--muted);
  margin: 0 0 1.25rem;
}
.required-legend span { color: var(--error); margin-right: 0.15rem; }

.contact-form { display: flex; flex-direction: column; gap: 1.25rem; }

.form-field { display: flex; flex-direction: column; gap: 0.375rem; }

.form-field label {
  font-weight: 600;
  font-size: 0.95rem;
}

.required-mark {
  color: var(--error);
  margin-left: 0.15rem;
}

.optional-mark {
  font-weight: 400;
  color: var(--muted);
  font-size: 0.875rem;
  margin-left: 0.25rem;
}

.form-field input {
  font: inherit;
  color: var(--text);
  background: #fff;
  padding: 0.65rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.form-field input::placeholder { color: #94a3b8; }

.form-field input:hover { border-color: var(--border-strong); }

.form-field input:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

.form-field input[aria-invalid="true"] {
  border-color: var(--error);
  background: var(--error-bg);
}

.field-help {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.field-error {
  margin: 0;
  font-size: 0.875rem;
  color: var(--error);
  font-weight: 500;
}

.form-actions { margin-top: 0.5rem; }

.btn-primary {
  font: inherit;
  font-weight: 600;
  background: var(--primary);
  color: #fff;
  border: 1px solid var(--primary);
  padding: 0.7rem 1.25rem;
  border-radius: var(--radius);
  cursor: pointer;
  min-height: 44px;
  transition: background-color 120ms ease;
}

.btn-primary:hover { background: var(--primary-hover); border-color: var(--primary-hover); }

.btn-primary:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.form-status {
  min-height: 1.25rem;
  font-size: 0.95rem;
  color: var(--muted);
}
.form-status.is-success { color: #15803d; font-weight: 500; }

@media (forced-colors: active) {
  .form-field input { border: 1px solid CanvasText; }
  .form-field input[aria-invalid="true"] { border-color: Mark; }
  .btn-primary { border: 1px solid ButtonText; }
}

@media (max-width: 480px) {
  .card { padding: 1.5rem; border-radius: 12px; }
  .page { padding: 1rem; }
}
