AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_01PUKpZLZEWTt17oPZyFjCZ8', arguments={'file_text': "(function () {
  const form = document.getElementById('contact-form');
  const status = document.getElementById('form-status');

  const fields = {
    name: {
      input: document.getElementById('name'),
      error: document.getElementById('name-error'),
      validate(value) {
        if (!value.trim()) return 'Error: Enter your full name.';
        return '';
      },
    },
    email: {
      input: document.getElementById('email'),
      error: document.getElementById('email-error'),
      validate(value) {
        const v = value.trim();
        if (!v) return 'Error: Enter your email address.';
        // Simple, permissive email pattern: something@something.tld
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!re.test(v)) return 'Error: Enter a valid email like name@example.com.';
        return '';
      },
    },
    phone: {
      input: document.getElementById('phone'),
      error: document.getElementById('phone-error'),
      validate(value) {
        const v = value.trim();
        if (!v) return ''; // optional
        // Allow digits, spaces, parentheses, dashes, dots, optional leading +
        const allowed = /^\+?[0-9\s().\-]{7,}$/;
        const digitCount = (v.match(/\d/g) || []).length;
        if (!allowed.test(v) || digitCount < 7 || digitCount > 15) {
          return 'Error: Enter a valid phone number, e.g. +1 555 123 4567.';
        }
        return '';
      },
    },
  };

  function setError(field, message) {
    if (message) {
      field.error.textContent = message;
      field.error.hidden = false;
      field.input.setAttribute('aria-invalid', 'true');
    } else {
      field.error.textContent = '';
      field.error.hidden = true;
      field.input.removeAttribute('aria-invalid');
    }
  }

  // Validate on blur; re-validate on input only if currently invalid (avoid noise).
  Object.values(fields).forEach((field) => {
    field.input.addEventListener('blur', () => {
      setError(field, field.validate(field.input.value));
    });
    field.input.addEventListener('input', () => {
      if (field.input.getAttribute('aria-invalid') === 'true') {
        setError(field, field.validate(field.input.value));
      }
    });
  });

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    status.textContent = '';
    status.classList.remove('is-success');

    let firstInvalid = null;
    Object.values(fields).forEach((field) => {
      const message = field.validate(field.input.value);
      setError(field, message);
      if (message && !firstInvalid) firstInvalid = field.input;
    });

    if (firstInvalid) {
      firstInvalid.focus();
      status.textContent = 'Please fix the highlighted fields and try again.';
      return;
    }

    status.textContent = 'Thanks! Your message has been sent. We\u2019ll be in touch soon.';
    status.classList.add('is-success');
    form.reset();
  });
})();
